using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class TurnipChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var r=new ResourceState{wheat=3};var p=r.Ensure("plot",VillageResource.Wheat);p.remaining=0;Require(r.Sow(p.id,FoodCrop.Turnip)&&r.wheat==2&&r.seedUsed==1&&!r.Sow(p.id,FoodCrop.Turnip),"Turnip seed accounting invalid");Require(!r.Grow(p.id,45)&&p.growth==.5f&&r.Grow(p.id,45)&&p.remaining==8,"Turnip timing/yield invalid");Require(r.Harvest(0,p.id,3)==3,"Turnip harvest failed");r.Recover(0);Require(p.remaining==8&&r.freshFood==0,"Canceled turnip cargo lost food");r.Harvest(0,p.id,3);Require(r.Deposit(0)==3&&r.freshFood==3&&r.wheat==2&&r.Deposit(0)==0,"Fresh deposit duplicated or became seed grain");r.Consume(90,1,2);Require(r.wheat==2&&r.consumed==1&&r.freshFood<2&&r.spoiled>0,"Fresh food not eaten first, stale or seed protected");Require(JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(r)).Valid(),"Turnip save invalid");var saved=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(r));saved.freshFood=48;Require(!saved.Valid(),"Fresh food ignored shared capacity");saved=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(r));saved.Find(p.id).remaining=9;Require(!saved.Valid(),"Turnip source exceeded yield");Require(new SliceState().Valid(),"Legacy save invalid");
  var full=new ResourceState{wheat=48};var root=full.Ensure("root",VillageResource.Wheat);root.crop=FoodCrop.Turnip;root.remaining=8;full.Harvest(0,root.id,3);Require(full.Deposit(0)==0&&root.remaining==8&&full.exposedWheat==0,"Fresh overflow became dry grain or vanished");
  Debug.Log("BWVR_TURNIP_MODEL_PASS");
 }
 [MenuItem("BWVR/Verify turnip farming (Play mode)")]
 public static void Verify(){VerifyModel();Require(Application.isPlaying,"Enter Play mode");var w=UnityEngine.Object.FindAnyObjectByType<VillageResources>();var slice=w.GetComponentInParent<QuestSlice>();var f=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)f.GetValue(slice);var actors=w.Gatherers;var positions=actors.Select(a=>a.transform.position).ToArray();slice.GetComponentInChildren<CreatureHybrid>().Interrupt("Turnip QA");foreach(var a in actors){a.Cancel();a.GetComponent<VillagerSocial>().ResetTask();a.GetComponent<VillagerExploration>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();}var test=new SliceState{developmentFocus=true};test.Resources.wheat=8;f.SetValue(slice,test);w.ResetWorld();
  try{var node=w.sources.First(s=>s.kind==VillageResource.Wheat&&!s.expansion);var record=test.Resources.Find(node.id);record.remaining=0;var actor=actors[0];actor.transform.position=node.approach;actor.GetComponent<IslandNavigator>().ResetRoute();Require(w.ChooseCrop()==FoodCrop.Turnip&&actor.TrySow(node,w.ChooseCrop())&&actor.PlannedCrop==FoodCrop.Turnip,"Short reserve did not choose turnips");Require(w.ChooseCrop()==FoodCrop.Wheat&&!actors[1].TrySow(node,FoodCrop.Turnip),"Pending root plot not exclusive");actor.Tick(30,true);Require(test.Resources.seedUsed==0&&!record.growing,"Pause planted turnips");actor.Cancel();Require(test.Resources.wheat==8,"Cancel spent seed");Require(actor.TrySow(node,FoodCrop.Turnip),"Cannot retry turnips");for(int i=0;i<3000&&actor.Active;i++)actor.Tick(.05f,false);Require(record.growing&&record.crop==FoodCrop.Turnip&&test.Resources.seedUsed==1&&w.ChooseCrop()==FoodCrop.Wheat,"Paid turnip sowing/growing cap failed");test.Resources.Grow(node.id,45);w.Refresh();Require(node.visual.Find("Turnip leaves and roots")!=null&&!node.visual.GetChild(0).gameObject.activeSelf&&!w.Available(node),"Turnip art missing or immature harvest enabled");float growth=record.growth;w.Advance(30,true);Require(record.growth==growth,"Paused turnips grew");test.Resources.Grow(node.id,45);w.Refresh();Require(record.remaining==8&&w.Available(node),"Ripe turnips unavailable");Require(actor.TryBegin(node),"Cannot harvest turnips");for(int i=0;i<4000&&actor.Active;i++)actor.Tick(.05f,false);Require(test.Resources.freshFood==3&&test.Resources.wheat==7&&record.remaining==5,"Native turnip delivery invalid");w.Refresh();Require(w.transform.Find("Fresh turnip crate").gameObject.activeSelf&&w.MealGrain==10,"Fresh storage/meal reserve missing");Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Native crop season cannot save");Require(node.visual.GetComponentsInChildren<Collider>(true).Length==0,"Turnip art added collisions");Debug.Log("BWVR_TURNIP_RUNTIME_PASS: autonomous choice, plot/seed exclusivity, pause/cancel, paid sowing, art/growth, finite fresh delivery, reserve and saved crop");
  }finally{foreach(var a in actors)a.Cancel();f.SetValue(slice,original);w.ResetWorld();for(int i=0;i<actors.Length;i++){actors[i].transform.position=positions[i];actors[i].GetComponent<IslandNavigator>().ResetRoute();}}
 }
}
}
